class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        count = defaultdict(int)
        count[0] = 1                    # 空前缀
        pre = res = 0
        for x in nums:
            pre += x
            res += count[pre - k]       # 先查
            count[pre] += 1             # 再存
        return res

