class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        count.put(0, 1);                                // 空前缀
        int pre = 0, res = 0;
        for (int x : nums) {
            pre += x;
            res += count.getOrDefault(pre - k, 0);      // 先查
            count.merge(pre, 1, Integer::sum);          // 再存
        }
        return res;
    }
}

