class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> count;
        count[0] = 1;                                   // 空前缀
        int pre = 0, res = 0;
        for (int x : nums) {
            pre += x;
            auto it = count.find(pre - k);              // 先查
            if (it != count.end()) res += it->second;
            count[pre]++;                               // 再存
        }
        return res;
    }
};

