func subarraySum(nums []int, k int) int {
	count := map[int]int{0: 1} // 空前缀
	pre, res := 0, 0
	for _, x := range nums {
		pre += x
		res += count[pre-k] // 先查
		count[pre]++        // 再存
	}
	return res
}

