var subarraySum = function(nums, k) {
    const count = new Map([[0, 1]]);                // 空前缀
    let pre = 0, res = 0;
    for (const x of nums) {
        pre += x;
        res += count.get(pre - k) || 0;             // 先查
        count.set(pre, (count.get(pre) || 0) + 1);  // 再存
    }
    return res;
};

